// Package amalg compiles only the pinned amalgamation (sqlite3.c, generated by
// ../../gen-amalgamation.sh) with the course's compile options. It is kept apart from the Go
// wrapper so that editing wrapper code does not recompile 9.5 MB of C (≈75 s on vm-1).
// Import it for its side effect: `import _ ".../cgo/amalg"`.
package amalg

/*
#cgo CFLAGS: -O2 -DSQLITE_THREADSAFE=1 -DHAVE_USLEEP=1 -DSQLITE_DQS=0
#cgo CFLAGS: -DSQLITE_ENABLE_SNAPSHOT -DSQLITE_ENABLE_DBPAGE_VTAB -DSQLITE_ENABLE_DBSTAT_VTAB
#cgo CFLAGS: -DSQLITE_ENABLE_SESSION -DSQLITE_ENABLE_PREUPDATE_HOOK -DSQLITE_ENABLE_EXPLAIN_COMMENTS
#cgo LDFLAGS: -lm
*/
import "C"
